from pathlib import Path
import subprocess,json,hashlib,numpy as np
from PIL import Image,ImageDraw
r=Path(__file__).parent;p=r/'00-Onion-Tears-1080p-Review-v1.mp4';tl=json.loads((r/'timeline.json').read_text());out=json.loads((r/'OUTPUT.json').read_text());assert out['status']=='ARCHIVED_UNREVIEWED','Archive exact MP4 before extended output review'
subprocess.run(['ffmpeg','-v','error','-xerror','-threads','2','-i',str(p),'-map','0:v:0','-map','0:a:0','-f','null','-'],check=True)
probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(p)]));v=next(x for x in probe['streams']if x['codec_type']=='video');a=next(x for x in probe['streams']if x['codec_type']=='audio');assert int(v['nb_read_frames'])==tl['frames'];assert(v['width'],v['height'])==(1080,1920)
load=lambda x:np.frombuffer(subprocess.check_output(['ffmpeg','-v','error','-i',str(x),'-f','f32le','-ar','48000','-ac','2','-']),np.float32).reshape(-1,2).copy()
ref=load(r/'Onion-Mix-v1.flac');enc=load(p);n=min(len(ref),len(enc));ref=ref[:n];enc=enc[:n];lo=int(34*48000);hi=int(38.1*48000);tail_corr=float(np.corrcoef(ref[lo:hi].ravel(),enc[lo:hi].ravel())[0,1]);assert tail_corr>.97
qa=r/'qa';qa.mkdir(exist_ok=True);times=[.15,.6,1.8,3.8,5.15,5.9,8.2,9.98,10.8,13.6,14.47,15.4,17.9,18.66,19.5,20.8,21.36,22.5,25,26.52,27.4,30.8,33.8,35.8,37.9,39.6]
for t in times:subprocess.run(['ffmpeg','-y','-v','error','-ss',str(t),'-i',str(p),'-frames:v','1','-vf','scale=270:480','-q:v','2',str(qa/f'{t:05.2f}.jpg')],check=True)
sheet=Image.new('RGB',(1080,7*510),'#0D1C2B');draw=ImageDraw.Draw(sheet)
for k,t in enumerate(times):im=Image.open(qa/f'{t:05.2f}.jpg');x=k%4*270;y=k//4*510;sheet.paste(im,(x,y));draw.text((x+10,y+485),f'{t:.2f}s',fill='white')
sheet.save(qa/'Encoded-All-Scenes.jpg',quality=94)
report={'status':'TECHNICALLY_VERIFIED_COMPLETE_REVIEW_CANDIDATE','output_sha256':out['sha256'],'native':[v['width'],v['height']],'fps':v['r_frame_rate'],'decoded_frames':int(v['nb_read_frames']),'duration':probe['format']['duration'],'decode_errors':0,'audio':{'codec':a['codec_name'],'sample_rate':a['sample_rate'],'channels':a['channels'],'encoded_tail_vs_exact_mix_correlation':tail_corr,'last_script_word':'it','last_word_asr_end':tl['words'][-1]['end'],'complete_decoded_voice_end':tl['voice_edited_duration'],'endcard_starts':tl['ending_start'],'tail_clearance':tl['protected_tail'],'original_source_kept':True,'vo_tail_fade':False},'caption_words':len(tl['words']),'asr_reconciliation':'90lexical words match intended script; only punctuation hallucinations excluded','all_scenes_represented':[s['id']for s in tl['scenes']],'inspection_still_times':times,'inspection_sheet':'qa/Encoded-All-Scenes.jpg','finishing_proof':'FINISHING_QA.json','source_commit':out['source_commit'],'review_limits':['Owner motion and whole-film approval pending','Technical and ASR checks do not substitute for actual human listening or platform UI review','Cross-episode templating concern remains open; current art accepted for this production']};(r/'OUTPUT_QA.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
